/* apply-shabbat-fixes.js — idempotent post-processing of data/shabbat-data.js
 * (window.SIDURON_SHABBAT, generated by tools/extract-shabbat.py from seforim.db).
 *   node tools/apply-shabbat-fixes.js
 * extract-shabbat.py runs it (and then apply-hoshanot.js) automatically, so a
 * fresh extraction keeps these fixes. Each step is keyed by text, so it no-ops
 * when it was already applied or when the upstream text changes.
 *
 *  1. "על הנסים" — the DB prints the חנוכה and פורים paragraphs together with no
 *     condition, so they showed every Shabbat. Each block is split into a חנוכה
 *     copy (cond chanuka) and a פורים copy (cond purim); the shared opening lines
 *     ("בחנוכה ופורים אומרים…", "על הנסים ועל הפרקן…") go into both.
 *  2. "לדוד ה' אורי" (אשכנז) — only in its season (cond ledavid → ladavid_season).
 *  3. "ברכי נפשי" (אשכנז, שבת ראש חודש) — inserted before "לדוד" in שחרית
 *     (cond rh), text from tools/data-overrides/barchi_nafshi_ashkenaz.json.
 *  4. Removes "מי שברך לחיילי צה"ל" and "מי שברך לשבויים" (State/IDF content is
 *     dropped by policy, as in tools/build-services.js).
 */
'use strict';
const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '..');
const FILE = path.join(ROOT, 'data', 'shabbat-data.js');
const OV = path.join(__dirname, 'data-overrides');

// python json.dumps(ensure_ascii=False) spacing — the format extract-shabbat.py writes.
function dump(v) {
  if (Array.isArray(v)) return '[' + v.map(dump).join(', ') + ']';
  if (v && typeof v === 'object') return '{' + Object.keys(v).map(k => JSON.stringify(k) + ': ' + dump(v[k])).join(', ') + '}';
  return JSON.stringify(v);
}
const plain = s => String(s).replace(/<[^>]*>/g, ' ').replace(/[֑-ׇ]/g, '').replace(/\s+/g, ' ').trim();
const noCond = s => !s.cond || !s.cond.length;
const tagged = (s, c) => Object.assign({}, s, { cond: [c] });

/* ── 1. על הנסים ── */
const isIntro = s => /^בחנוכה (ו|וב)פורים/.test(plain(s.text));
const isChanMark = s => s.kind === 'header' ? /לחנוכה/.test(plain(s.text))
  : /^(בחנוכה אומרים|בחנוכה:|לחנוכה)/.test(plain(s.text));
const isPurimMark = s => s.kind === 'header' ? /לפורים/.test(plain(s.text))
  : /^(בפורים|לפורים)/.test(plain(s.text));
const isBlockStart = (arr, i) => noCond(arr[i]) && (isIntro(arr[i]) ||
  (arr[i].kind === 'header' && isChanMark(arr[i]) && arr[i + 1] && isIntro(arr[i + 1])) ||
  plain(arr[i].text) === 'ועל הנסים');
// סוף פסקת חנוכה: "להודות ולהלל לשמך הגדול" / "ונודה לשמך הגדול סלה"; פורים: "ותלו אותו ואת בניו על העץ".
const CHAN_END = /לשמך הגדול/, PURIM_END = /על ?העץ/;

// Parse one block from `s`: [chanuka header] shared… chanuka… [purim header] purim…
// Returns { end, chanuka: [...], purim: [...] } or null when it doesn't look right.
function parseBlock(arr, s) {
  let i = s, hc = null, hu = null;
  const shared = [], chan = [], pur = [];
  if (arr[i].kind === 'header' && isChanMark(arr[i])) hc = arr[i++];
  while (i < arr.length && noCond(arr[i]) && !isChanMark(arr[i]) && !isPurimMark(arr[i])) {
    shared.push(arr[i]);
    if (CHAN_END.test(plain(arr[i].text))) return { end: i + 1, chanuka: (hc ? [hc] : []).concat(shared), purim: [] }; // סדר בלי סימון (ספרד)
    i++;
  }
  while (i < arr.length && noCond(arr[i]) && !isPurimMark(arr[i])) {
    chan.push(arr[i]);
    if (CHAN_END.test(plain(arr[i++].text))) break;
  }
  if (!chan.length || !CHAN_END.test(plain(chan[chan.length - 1].text))) return null;
  if (i < arr.length && noCond(arr[i]) && isPurimMark(arr[i])) {
    if (arr[i].kind === 'header') hu = arr[i++];
    while (i < arr.length && noCond(arr[i])) {
      pur.push(arr[i]);
      if (PURIM_END.test(plain(arr[i++].text))) break;
    }
    if (!PURIM_END.test(plain(pur[pur.length - 1].text))) return null;
  }
  return {
    end: i,
    chanuka: (hc ? [hc] : []).concat(shared, chan),
    purim: pur.length ? (hu ? [hu] : []).concat(shared, pur) : [],
  };
}
function splitAlHanisim(arr) {
  let n = 0;
  for (let i = 0; i < arr.length; i++) {
    if (!isBlockStart(arr, i)) continue;
    const b = parseBlock(arr, i);
    if (!b) continue;
    const rep = b.chanuka.map(s => tagged(s, 'chanuka')).concat(b.purim.map(s => tagged(s, 'purim')));
    arr.splice(i, b.end - i, ...rep);
    i += rep.length - 1;
    n++;
  }
  return n;
}

/* ── 2. לדוד ה' אורי (אשכנז) ── */
function tagLedavid(arr) {
  let n = 0;
  for (let i = 0; i < arr.length; i++) {
    if (!(arr[i].kind === 'header' && plain(arr[i].text) === 'לדוד' && noCond(arr[i]))) continue;
    let j = i + 1;
    while (j < arr.length && arr[j].kind !== 'header') j++;
    if (!arr.slice(i + 1, j).some(s => /אורי וישעי/.test(plain(s.text)))) continue;
    // Only the psalm itself (ends "…חזק ויאמץ לבך וקוה אל ה'") — not a קדיש after it.
    let e = i + 1;
    while (e < j && !/ויאמץ לבך/.test(plain(arr[e].text))) e++;
    if (e >= j) continue;
    for (let k = i; k <= e; k++) arr[k] = tagged(arr[k], 'ledavid');
    n++;
  }
  return n;
}

/* ── 3. ברכי נפשי (אשכנז, שחרית) ── */
function insertBarchiNafshi(arr) {
  if (arr.some(s => (s.cond || []).indexOf('rh') >= 0 && /^ברכי נפשי/.test(plain(s.text)))) return 0;
  const at = arr.findIndex(s => s.kind === 'header' && plain(s.text) === 'לדוד');
  if (at < 0) return 0;
  const segs = JSON.parse(fs.readFileSync(path.join(OV, 'barchi_nafshi_ashkenaz.json'), 'utf8')).segments;
  arr.splice(at, 0, ...segs);
  return 1;
}

/* ── 4. מי שברך לחיילי צה"ל / לשבויים ── */
function dropMiSheberach(arr) {
  let n = 0;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (!(arr[i].kind === 'header' && /^מי שברך (לחיילי|לשבויים)/.test(plain(arr[i].text)))) continue;
    let j = i + 1;
    while (j < arr.length && arr[j].kind !== 'header') j++;
    arr.splice(i, j - i);
    n++;
  }
  return n;
}

const lines = fs.readFileSync(FILE, 'utf8').split('\n');
lines.forEach((l, li) => {
  const m = /^(window\.SIDURON_SHABBAT = )([\s\S]*?)(;\r?)$/.exec(l);
  if (!m) return;
  const o = JSON.parse(m[2]);
  if (dump(o) !== m[2]) throw new Error('round-trip mismatch in shabbat-data.js');
  Object.keys(o).forEach(nusach => Object.keys(o[nusach]).forEach(svc => {
    const arr = o[nusach][svc], log = [];
    let k;
    if ((k = dropMiSheberach(arr))) log.push('mi-sheberach -' + k);
    if ((k = splitAlHanisim(arr))) log.push('al-hanisim ' + k);
    if (nusach === 'ashkenaz') {
      if ((k = tagLedavid(arr))) log.push('ledavid ' + k);
      if (svc === 'shacharit' && (k = insertBarchiNafshi(arr))) log.push('barchi-nafshi');
    }
    if (log.length) console.log(nusach, svc + ':', log.join(', '));
  }));
  lines[li] = m[1] + dump(o) + m[3];
});
fs.writeFileSync(FILE, lines.join('\n'));
